import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from 'react-query';
import { getComments, addComment, updateComment, deleteComment, voteComment } from '../../api/prompts';
import { useAuth } from '../../contexts/AuthContext';
import { FiMessageSquare, FiEdit2, FiTrash2, FiThumbsUp, FiThumbsDown, FiCornerUpLeft } from 'react-icons/fi';
import toast from 'react-hot-toast';

const CommentForm = ({ promptId, parentId = null, onSuccess, onCancel }) => {
  const [content, setContent] = useState('');
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const addCommentMutation = useMutation(
    (commentData) => addComment(promptId, commentData),
    {
      onSuccess: () => {
        queryClient.invalidateQueries(['comments', promptId]);
        setContent('');
        onSuccess?.();
        toast.success('Comment added successfully!');
      },
      onError: (error) => {
        const message = error.response?.data?.message || 'Failed to add comment';
        toast.error(message);
      },
    }
  );

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!content.trim()) return;

    addCommentMutation.mutate({
      content: content.trim(),
      parent: parentId
    });
  };

  if (!user) {
    return (
      <div className="text-center py-4 text-gray-500">
        Please login to add a comment
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="mb-4">
      <textarea
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Write a comment..."
        className="w-full p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
        rows="3"
        disabled={addCommentMutation.isLoading}
      />
      <div className="flex justify-end space-x-2 mt-2">
        {onCancel && (
          <button
            type="button"
            onClick={onCancel}
            className="px-4 py-2 text-gray-600 hover:text-gray-800 transition-colors"
          >
            Cancel
          </button>
        )}
        <button
          type="submit"
          disabled={!content.trim() || addCommentMutation.isLoading}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {addCommentMutation.isLoading ? 'Posting...' : 'Post Comment'}
        </button>
      </div>
    </form>
  );
};

const CommentVoteButtons = ({ comment, size = 'sm' }) => {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const voteMutation = useMutation(
    ({ commentId, voteType }) => voteComment(commentId, voteType),
    {
      onSuccess: () => {
        queryClient.invalidateQueries(['comments']);
        toast.success('Vote recorded!');
      },
      onError: (error) => {
        const message = error.response?.data?.message || 'Failed to vote';
        toast.error(message);
      },
    }
  );

  const handleVote = (voteType) => {
    if (!user) {
      toast.error('Please login to vote');
      return;
    }

    voteMutation.mutate({ commentId: comment._id, voteType });
  };

  const userVote = comment.getUserVote?.(user?._id) || 
    (comment.upvotes?.some(id => id === user?._id) ? 'upvote' : 
     comment.downvotes?.some(id => id === user?._id) ? 'downvote' : null);

  const voteCount = comment.voteCount || 
    (comment.upvotes?.length || 0) - (comment.downvotes?.length || 0);

  const iconSizes = {
    sm: 'w-3 h-3',
    md: 'w-4 h-4',
    lg: 'w-5 h-5'
  };

  return (
    <div className="flex items-center space-x-1">
      <button
        onClick={() => handleVote('upvote')}
        disabled={voteMutation.isLoading}
        className={`p-1 rounded transition-colors ${
          userVote === 'upvote'
            ? 'text-green-600'
            : 'text-gray-400 hover:text-green-600'
        }`}
      >
        <FiThumbsUp className={iconSizes[size]} />
      </button>
      
      <span className="text-xs font-medium text-gray-500 min-w-[20px] text-center">
        {voteCount}
      </span>
      
      <button
        onClick={() => handleVote('downvote')}
        disabled={voteMutation.isLoading}
        className={`p-1 rounded transition-colors ${
          userVote === 'downvote'
            ? 'text-red-600'
            : 'text-gray-400 hover:text-red-600'
        }`}
      >
        <FiThumbsDown className={iconSizes[size]} />
      </button>
    </div>
  );
};

const CommentItem = ({ comment, promptId, onReply }) => {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState(comment.content);

  const updateCommentMutation = useMutation(
    (commentData) => updateComment(comment._id, commentData),
    {
      onSuccess: () => {
        queryClient.invalidateQueries(['comments']);
        setIsEditing(false);
        toast.success('Comment updated successfully!');
      },
      onError: (error) => {
        const message = error.response?.data?.message || 'Failed to update comment';
        toast.error(message);
      },
    }
  );

  const deleteCommentMutation = useMutation(
    () => deleteComment(comment._id),
    {
      onSuccess: () => {
        queryClient.invalidateQueries(['comments']);
        toast.success('Comment deleted successfully!');
      },
      onError: (error) => {
        const message = error.response?.data?.message || 'Failed to delete comment';
        toast.error(message);
      },
    }
  );

  const handleEdit = (e) => {
    e.preventDefault();
    if (!editContent.trim()) return;

    updateCommentMutation.mutate({ content: editContent.trim() });
  };

  const handleDelete = () => {
    if (window.confirm('Are you sure you want to delete this comment?')) {
      deleteCommentMutation.mutate();
    }
  };

  const canEdit = user && (comment.author._id === user._id || user.isAdmin);
  const canDelete = user && (comment.author._id === user._id || user.isAdmin);

  return (
    <div className="border-b border-gray-200 dark:border-gray-700 py-4">
      <div className="flex items-start space-x-3">
        <div className="flex-shrink-0">
          <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center">
            <span className="text-sm font-medium text-gray-600">
              {comment.author.username?.charAt(0).toUpperCase()}
            </span>
          </div>
        </div>
        
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2 mb-1">
            <span className="text-sm font-medium text-gray-900 dark:text-white">
              {comment.author.username}
            </span>
            <span className="text-xs text-gray-500">
              {new Date(comment.createdAt).toLocaleDateString()}
            </span>
            {comment.isEdited && (
              <span className="text-xs text-gray-400">(edited)</span>
            )}
          </div>
          
          {isEditing ? (
            <form onSubmit={handleEdit} className="mb-2">
              <textarea
                value={editContent}
                onChange={(e) => setEditContent(e.target.value)}
                className="w-full p-2 border border-gray-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500"
                rows="3"
                disabled={updateCommentMutation.isLoading}
              />
              <div className="flex justify-end space-x-2 mt-2">
                <button
                  type="button"
                  onClick={() => setIsEditing(false)}
                  className="text-sm text-gray-600 hover:text-gray-800"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={!editContent.trim() || updateCommentMutation.isLoading}
                  className="text-sm px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                >
                  Save
                </button>
              </div>
            </form>
          ) : (
            <p className="text-gray-700 dark:text-gray-300 mb-2">
              {comment.content}
            </p>
          )}
          
          <div className="flex items-center space-x-4">
            <CommentVoteButtons comment={comment} />
            
            <button
              onClick={() => onReply(comment._id)}
              className="flex items-center space-x-1 text-xs text-gray-500 hover:text-gray-700 transition-colors"
            >
              <FiReply className="w-3 h-3" />
              <span>Reply</span>
            </button>
            
            {canEdit && (
              <button
                onClick={() => setIsEditing(true)}
                className="flex items-center space-x-1 text-xs text-gray-500 hover:text-gray-700 transition-colors"
              >
                <FiEdit2 className="w-3 h-3" />
                <span>Edit</span>
              </button>
            )}
            
            {canDelete && (
              <button
                onClick={handleDelete}
                disabled={deleteCommentMutation.isLoading}
                className="flex items-center space-x-1 text-xs text-red-500 hover:text-red-700 transition-colors"
              >
                <FiTrash2 className="w-3 h-3" />
                <span>Delete</span>
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

const CommentsSection = ({ promptId }) => {
  const [showCommentForm, setShowCommentForm] = useState(false);
  const [replyingTo, setReplyingTo] = useState(null);

  const { data: commentsData, isLoading, error } = useQuery(
    ['comments', promptId],
    () => getComments(promptId),
    {
      refetchOnWindowFocus: false,
    }
  );

  const handleReply = (commentId) => {
    setReplyingTo(commentId);
    setShowCommentForm(true);
  };

  const handleCommentSuccess = () => {
    setShowCommentForm(false);
    setReplyingTo(null);
  };

  if (isLoading) {
    return (
      <div className="mt-6">
        <h3 className="text-lg font-semibold mb-4">Comments</h3>
        <div className="animate-pulse space-y-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="flex space-x-3">
              <div className="w-8 h-8 bg-gray-300 rounded-full"></div>
              <div className="flex-1">
                <div className="h-4 bg-gray-300 rounded w-1/4 mb-2"></div>
                <div className="h-3 bg-gray-300 rounded w-full"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="mt-6">
        <h3 className="text-lg font-semibold mb-4">Comments</h3>
        <div className="text-red-500">Failed to load comments</div>
      </div>
    );
  }

  const comments = commentsData?.comments || [];

  return (
    <div className="mt-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold flex items-center space-x-2">
          <FiMessageSquare className="w-5 h-5" />
          <span>Comments ({comments.length})</span>
        </h3>
        
        {!showCommentForm && (
          <button
            onClick={() => setShowCommentForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Add Comment
          </button>
        )}
      </div>

      {showCommentForm && (
        <div className="mb-6">
          <CommentForm
            promptId={promptId}
            parentId={replyingTo}
            onSuccess={handleCommentSuccess}
            onCancel={() => {
              setShowCommentForm(false);
              setReplyingTo(null);
            }}
          />
        </div>
      )}

      <div className="space-y-4">
        {comments.length === 0 ? (
          <div className="text-center py-8 text-gray-500">
            No comments yet. Be the first to comment!
          </div>
        ) : (
          comments.map((comment) => (
            <CommentItem
              key={comment._id}
              comment={comment}
              promptId={promptId}
              onReply={handleReply}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default CommentsSection;
